from wire.codec import encode, decode, CodecError
d = bytearray(encode([{"ts": 5, "sensor_id": 2, "value": 1.5, "flags": 9}]))
d[-3] ^= 0x01
for bad in (bytes(d), b"", d + b"x", encode([])[:-1]):
    try: decode(bad); print("NO RAISE", bad)
    except CodecError as e: print("ok:", e)
EOF
